        alias=evidence.get('historical_source_alias_remaps',{}).get(r['source_path'],r['source_path'])
        b=source(r['archive_path']);need(b==archived(alias) and sha(b)==r['sha256'] and len(b)==r['bytes'],'Original source alias differs')
