    mapping=json.loads(source('SOURCE_MAP.json'));candidate=source('CANDIDATE.md');parts=mapping['parts'];cores=[]
    need(len(parts)==3 and candidate==b''.join(source(r['assembly_path']) for r in parts),'Accepted parts do not reconstruct')
    wrapper=source(parts[0]['assembly_path']);core=source(parts[2]['assembly_path']);i,j=parts[2]['candidate_byte_start_inclusive'],parts[2]['candidate_byte_end_exclusive']
    need(sha(candidate)==mapping['candidate']['sha256'] and sha(core)==mapping['complete_core_sha256']==CORE_SHAS[0] and candidate[i:j]==core and candidate.count(core)==1,'Complete original proof differs')
    need(candidate[:i].count(b'\n')+1==parts[2]['candidate_line_start_1based'] and candidate[:j].count(b'\n')==parts[2]['candidate_line_end_inclusive'],'Accepted extraction lines differ');cores.append(core)
    edits=pinned('PUBLICATION_EDITS.json',EDITS_SHA,'Publication transformation changed')
