    note=edits['notes'][0];rendered_wrapper=wrapper
    for t in edits['wrapper_replacements']:
        a,b=t['original'].encode(),t['rendered'].encode()
        need(t['scope']=='publication metadata or current source-status pointer only' and rendered_wrapper.count(a)==1,'Wrapper replacement differs');rendered_wrapper=rendered_wrapper.replace(a,b,1)
    raw_core=cores[0];rendered_core=raw_core
    need(len(edits['body_link_rendering']['targets'])==3 and edits['body_link_rendering']['scope']=='exactly three historical Markdown target relocations; no mathematical edit','Body rendering scope differs')
    for r in edits['body_link_rendering']['targets']:
        a,b=r['before_token'].encode(),r['after_token'].encode()
