    need(len(rows)==len(remaps)==3 and remaps=={r['original_alias']:r['historical_snapshot_alias'] for r in rows},'Historical canonical remap differs')
    need(set(remaps)=={p['archive_alias'] for p in parents},'Historical remap scope differs')
    for r in rows:
        need(sha(archived(r['historical_snapshot_alias']))==r['historical_sha256'] and sha(archived(r['original_alias']))==r['current_sha256'],'Historical/current canonical identities differ')
